    # Check if the block is a blockquote
    if block.startswith('> '):
        # Remove the "> " from each line and join them with <br>
        blockquote_content = '<br>'.join(line[2:] for line in block.splitlines())
        processed_block = f'<blockquote>{blockquote_content}</blockquote>'
    else:
        # Replace & with &amp;, < with &lt;, and > with &gt;
        escaped_block = block.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
